using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class CityMobileOptimizationAudit{
static CityMobileOptimizationAudit(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("CityMobileOptimizationAudit.request"))return;File.Delete("CityMobileOptimizationAudit.request");try{Run();}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/MobileOptimizationAudit.txt",e.ToString());}}
public static string Signature(Material m){string p=AssetDatabase.GetAssetPath(m);if(!File.Exists(p))return "builtin:"+m.GetInstanceID();string t=File.ReadAllText(p);t=System.Text.RegularExpressions.Regex.Replace(t,@"(?m)^  m_Name:.*$","");return t;}
static void Run(){var sc=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var roots=sc.GetRootGameObjects();var rs=roots.SelectMany(g=>g.GetComponentsInChildren<Renderer>(true)).ToArray();var fs=roots.SelectMany(g=>g.GetComponentsInChildren<MeshFilter>(true)).Where(f=>f.sharedMesh).ToArray();var mats=rs.SelectMany(r=>r.sharedMaterials).Where(m=>m).Distinct().ToArray();var lods=roots.SelectMany(g=>g.GetComponentsInChildren<LODGroup>(true)).ToArray();var s=new StringBuilder();s.AppendLine("Scene="+sc.path+" renderers="+rs.Length+" activeRenderers="+rs.Count(r=>r.enabled&&r.gameObject.activeInHierarchy)+" meshFilters="+fs.Length+" uniqueMeshes="+fs.Select(f=>f.sharedMesh).Distinct().Count()+" materials="+mats.Length+" lodGroups="+lods.Length);s.AppendLine("Triangles all source renderers incl LODs="+fs.Sum(f=>Enumerable.Range(0,f.sharedMesh.subMeshCount).Sum(i=>(long)f.sharedMesh.GetIndexCount(i)/3)));foreach(var g in mats.GroupBy(Signature).Where(g=>g.Count()>1))s.AppendLine("DUPLICATE "+string.Join(" | ",g.Select(AssetDatabase.GetAssetPath)));foreach(var g in fs.Where(f=>!f.GetComponentInParent<LODGroup>()&&f.GetComponent<MeshRenderer>()).GroupBy(f=>f.GetComponent<MeshRenderer>().sharedMaterial?f.GetComponent<MeshRenderer>().sharedMaterial.name:"none").OrderByDescending(g=>g.Sum(f=>(long)f.sharedMesh.GetIndexCount(0)))){s.AppendLine("UNMANAGED MATERIAL "+g.Key+" objects="+g.Count()+" triangles="+g.Sum(f=>Enumerable.Range(0,f.sharedMesh.subMeshCount).Sum(i=>(long)f.sharedMesh.GetIndexCount(i)/3)));foreach(var f in g.OrderByDescending(f=>f.sharedMesh.vertexCount).Take(5))s.AppendLine("  "+f.name+" tri="+Enumerable.Range(0,f.sharedMesh.subMeshCount).Sum(i=>(long)f.sharedMesh.GetIndexCount(i)/3)+" size="+f.GetComponent<Renderer>().bounds.size+" path="+AssetDatabase.GetAssetPath(f.sharedMesh));}s.AppendLine("LIGHTS="+roots.SelectMany(g=>g.GetComponentsInChildren<Light>(true)).Count()+" colliders="+roots.SelectMany(g=>g.GetComponentsInChildren<Collider>(true)).Count());foreach(var g in rs.SelectMany(r=>r.sharedMaterials).Where(m=>m).Distinct().GroupBy(m=>m.shader.name))s.AppendLine("SHADER "+g.Key+" mats="+g.Count());File.WriteAllText("FinalEnvironmentRoadReview/MobileOptimizationAudit.txt",s.ToString());}}
